// Auto-generated per-language descriptions for fr
// DO NOT EDIT - generated from descriptions.ts
export const descriptions_fr: Record<string, Record<string, string>> = {
  "length": {
    "mm": "Le millimètre (mm) est la plus petite unité métrique de longueur couramment utilisée, équivalente à un millième de mètre. Il est largement utilisé dans les dessins techniques, les tolérances de fabrication et les mesures de précipitations où la précision est importante. Un millimètre équivaut à environ 0,0394 pouces, ce qui le rend idéal pour décrire des matériaux fins comme le papier ou le fil.",
    "cm": "Le centimètre (cm) est une unité métrique de longueur égale à un centième de mètre, couramment utilisée pour les mesures quotidiennes dans le monde entier. Il apparaît sur les règles, dans les tailles de vêtements et dans les dossiers médicaux pour les mesures corporelles. Un centimètre équivaut à environ 0,3937 pouces, offrant une échelle pratique entre les millimètres et les mètres.",
    "m": "Le mètre (m) est l'unité de base de longueur dans le Système international d'unités, défini à l'origine par la distance parcourue par la lumière dans le vide en 1/299 792 458 de seconde. Il sert de base à toutes les mesures de longueur métriques et est utilisé dans la construction, le sport et la recherche scientifique dans le monde entier. Un mètre équivaut à environ 3,2808 pieds ou environ 1,0936 yards.",
    "km": "Le kilomètre (km) équivaut à 1 000 mètres et est l'unité standard pour mesurer de longues distances entre les villes, les pays et les caractéristiques géographiques. Les panneaux routiers dans la plupart des pays affichent les distances en kilomètres, et les courses à pied utilisent couramment des repères kilométriques. Un kilomètre est équivalent à environ 0,6214 mile, ce qui facilite la conversion entre les échelles de distance métriques et impériales.",
    "inch": "Le pouce (in) est une unité impériale de longueur égale exactement à 25,4 millimètres, largement utilisée aux États-Unis, au Canada et au Royaume-Uni. C'est la mesure standard pour les tailles d'écran, les diamètres de tuyaux et les fixations mécaniques, et elle reste courante dans l'usage quotidien en Amérique du Nord. Un pouce équivaut exactement à 2,54 centimètres.",
    "foot": "Le pied (ft) est une unité impériale égale à 12 pouces ou 0,3048 mètre, profondément ancrée dans la construction américaine, les altitudes en aviation et les mesures quotidiennes. Dans l'immobilier, les dimensions des pièces et la taille des terrains sont presque toujours indiquées en pieds à travers les États-Unis. Un pied équivaut exactement à 30,48 centimètres.",
    "yard": "Le yard (yd) est une unité impériale égale à 3 pieds ou 0,9144 mètre, communément utilisée aux États-Unis pour mesurer les tissus, les terrains de football et les distances de longueur moyenne. Il offre un compromis pratique entre le pied et le mile pour les mesures en extérieur. Un yard équivaut exactement à 0,9144 mètre, ce qui est suffisamment proche d'un mètre pour des estimations rapides.",
    "mile": "Le mile (mi) est une unité de distance impériale égale à 5 280 pieds ou environ 1,6093 kilomètres, utilisée principalement aux États-Unis et au Royaume-Uni pour les distances routières. Les limites de vitesse sur les autoroutes américaines sont affichées en miles par heure, et les coureurs utilisent souvent le mile comme distance de référence. Un mile équivaut à environ 1,609 kilomètres."
  },
  "weight": {
    "mg": "Le milligramme (mg) est une petite unité métrique de masse équivalente à un millième de gramme, essentielle dans les produits pharmaceutiques et l'étiquetage nutritionnel. Les doses de médicaments, la teneur en vitamines et les quantités d'additifs alimentaires sont généralement exprimées en milligrammes. Un milligramme équivaut à environ 0,0000353 onces, ce qui en fait l'unité de référence pour mesurer des masses extrêmement petites.",
    "g": "Le gramme (g) est l'unité de base de la masse dans le système métrique, définie comme le millième d'un kilogramme. C'est la mesure standard pour les portions alimentaires, les tarifs postaux et les petits objets dans la vie quotidienne à travers la plupart du monde. Un gramme équivaut à environ 0,0353 onces, et un trombone standard pèse à peu près un gramme.",
    "kg": "Le kilogramme (kg) est l'unité de base de la masse dans le Système international d'unités, défini par la constante de Planck depuis 2019. C'est l'unité de masse la plus utilisée dans le monde pour le poids corporel, les articles d'épicerie et l'expédition, apparaissant sur les balances dans les maisons et les marchés partout. Un kilogramme équivaut à environ 2,2046 livres.",
    "tonne": "La tonne métrique ou tonne (t) équivaut à 1 000 kilogrammes et est utilisée pour mesurer les cargaisons lourdes, la production industrielle et le poids des véhicules dans le monde entier. Les conteneurs maritimes, la production d'acier et les émissions de gaz à effet de serre sont tous couramment rapportés en tonnes. Une tonne équivaut à environ 2 204,6 livres ou environ 1,1023 tonnes courtes.",
    "oz": "L'once (oz) est une unité de poids impériale équivalente à environ 28,35 grammes, largement utilisée aux États-Unis pour l'emballage des aliments, les services postaux et les métaux précieux. En cuisine, les recettes indiquent souvent les ingrédients en onces, et l'or et l'argent se négocient en onces troy. Une once équivaut à environ 28,35 grammes.",
    "lb": "La livre (lb) est une unité impériale de masse égale exactement à 0,45359237 kilogrammes, servant d'unité de poids principale aux États-Unis et dans certaines parties du Commonwealth britannique. Le poids corporel, les équipements de gym et les produits emballés en Amérique sont presque toujours étiquetés en livres. Une livre équivaut à 16 onces ou à environ 0,4536 kilogramme.",
    "st": "La pierre (st) est une unité impériale britannique égale à 14 livres ou environ 6,35 kilogrammes, traditionnellement utilisée au Royaume-Uni et en Irlande pour le poids du corps. Lorsque quelqu'un au Royaume-Uni dit qu'il pèse 11 pierres, cela signifie 154 livres, une convention qui persiste dans la conversation quotidienne et les dossiers médicaux. Une pierre équivaut exactement à 6,35029 kilogrammes.",
    "jin": "Le jin (斤) est une unité de poids chinoise traditionnelle équivalente à 500 grammes, soit exactement une demi-kilogramme. Il reste l'unité de poids la plus courante dans les marchés chinois, les épiceries et la vie quotidienne, où les légumes, la viande et les fruits sont vendus au jin. Un jin équivaut à 1,1023 livres ou exactement 500 grammes."
  },
  "temperature": {
    "c": "Le Celsius (°C) est l'échelle de température la plus utilisée dans le monde, où 0°C marque le point de congélation de l'eau et 100°C son point d'ébullition à la pression atmosphérique standard. Il sert d'unité de température par défaut dans presque tous les pays sauf les États-Unis, apparaissant dans les prévisions météorologiques, les instructions de cuisson et la littérature scientifique. Pour convertir des degrés Celsius en Fahrenheit, multipliez par 9/5 et ajoutez 32.",
    "f": "Fahrenheit (°F) est une échelle de température où 32°F marque le point de congélation de l'eau et 212°F son point d'ébullition, principalement utilisée aux États-Unis pour la météo, la cuisine et les références de température quotidiennes. Elle offre une granularité plus fine que le Celsius, chaque degré représentant un changement de température plus petit. Pour convertir Fahrenheit en Celsius, soustrayez 32 et multipliez par 5/9.",
    "k": "Le kelvin (K) est l'unité de base de la température thermodynamique dans le Système international d'unités, où 0 K représente le zéro absolu, le point théorique d'énergie thermique nulle. Les scientifiques utilisent le kelvin en physique, en chimie et en astronomie car il commence à zéro véritable sans valeurs négatives, ce qui rend les calculs simples. Zéro degré Celsius équivaut à 273,15 kelvins, et les deux échelles ont la même taille d'incrément de degré."
  },
  "data": {
    "bit": "Le bit est l'unité la plus fondamentale de l'information numérique, représentant une seule valeur binaire de 0 ou 1. Chaque morceau de données stocké ou transmis sur Internet est finalement composé de bits, d'un seul caractère de texte aux flux vidéo haute définition. Huit bits forment un octet, c'est pourquoi le stockage des données est généralement discuté en octets plutôt qu'en bits.",
    "b": "L'octet (B) est l'unité standard de stockage numérique composée de 8 bits, suffisante pour représenter un seul caractère comme une lettre ou un chiffre. Les tailles de fichiers, la capacité de mémoire et les dispositifs de stockage sont tous mesurés en octets ou en leurs multiples, ce qui en fait l'unité la plus couramment référencée en informatique. Un octet équivaut exactement à 8 bits et peut représenter 256 valeurs distinctes.",
    "kb": "Le kilooctet (Ko) équivaut à 1 024 octets en termes de calcul binaire et est utilisé pour mesurer de petits fichiers tels que les documents texte, les messages électroniques et les images miniatures. Bien que le terme fasse parfois référence à 1 000 octets dans les contextes réseau, les systèmes d'exploitation utilisent systématiquement la définition binaire. Un kilooctet peut stocker environ la moitié d'une page de texte simple.",
    "mb": "Le mégaoctet (Mo) équivaut à 1 024 kilo-octets ou 1 048 576 octets, couramment utilisé pour décrire la taille des photos, des fichiers musicaux et des applications. Une photo typique de smartphone varie de 2 à 10 Mo, et une chanson unique au format MP3 fait environ 3 à 5 Mo. Il reste l'une des unités les plus fréquemment rencontrées lors de la gestion du stockage numérique personnel.",
    "gb": "Le gigaoctet (Go) équivaut à 1 024 mégaoctets ou environ 1,07 milliard d'octets, représentant la mesure standard de la capacité de stockage sur les téléphones, les ordinateurs portables et les clés USB. Un film HD typique nécessite de 2 à 4 Go d'espace, et la plupart des forfaits de données mobiles sont mesurés en gigaoctets par mois. Il comble le fossé entre les tailles de fichiers quotidiennes et le stockage de données à grande échelle.",
    "tb": "Le téraoctet (TB) équivaut à 1 024 gigaoctets ou à environ 1,1 billion d'octets, utilisé pour le stockage à grande échelle comme les disques durs, les sauvegardes cloud et les bases de données d'entreprise. Les disques durs externes modernes offrent généralement une capacité de 1 à 8 To, suffisante pour contenir des centaines de milliers de photos ou des milliers d'heures de vidéo. Un téraoctet représente une quantité massive de données selon les standards du consommateur moyen.",
    "pb": "Le pétaoctet (PB) équivaut à 1 024 téraoctets ou à environ 1,13 quadrillion d'octets, représentant des volumes de stockage utilisés par les grandes entreprises technologiques, les institutions de recherche et les plateformes cloud. Les principaux services de streaming, réseaux sociaux et ensembles de données scientifiques sont mesurés en pétaoctets en raison de l'énorme volume de contenu généré par les utilisateurs. Un pétaoctet peut stocker environ 500 milliards de pages de texte standard.",
    "kbit": "Le kilobit (Kbit) équivaut à 1 000 bits et est principalement utilisé pour mesurer les débits de transfert de données dans les réseaux, tels que les vitesses de connexion Internet. Les fournisseurs d'accès à Internet annoncent couramment les vitesses en kilobits par seconde (Kbps) ou en mégabits par seconde, faisant du kilobit une unité clé pour comprendre la bande passante. Un kilobit équivaut à 125 octets, ce qui le distingue clairement du kilooctet.",
    "mbit": "Le mégabit (Mbit) équivaut à 1 000 kilobits ou à un million de bits, couramment utilisé dans les évaluations de la vitesse d'Internet où les FAI annoncent des forfaits en mégabits par seconde (Mbps). Il est important de distinguer les mégabits des mégaoctets, car une connexion de 100 Mbps fournit environ 12,5 mégaoctets par seconde de vitesse de téléchargement réelle. Cette unité est essentielle pour comparer et comprendre les performances du réseau.",
    "gbit": "Le gigabit (Gbit) équivaut à 1 000 mégabits ou un milliard de bits, utilisé pour décrire les connexions réseau à haute vitesse et les interconnexions de centres de données. Les forfaits Internet à fibre optique modernes atteignent souvent des vitesses en gigabits, et les réseaux d'entreprise dépendent du débit au niveau du gigabit pour gérer de grands volumes de trafic. Un gigabit équivaut à 125 mégaoctets, ce qui souligne la différence pratique entre bits et octets."
  },
  "area": {
    "sqmm": "Le millimètre carré (mm²) est une unité métrique de superficie égale à un millionième de mètre carré, utilisée en ingénierie de précision, en microélectronique et en imagerie médicale. Il est idéal pour mesurer la surface transversale des fils, la surface des microprocesseurs et d'autres petites surfaces. Un millimètre carré équivaut à environ 0,00155 pouce carré.",
    "sqcm": "Le centimètre carré (cm²) est une unité métrique de superficie équivalente à un dix-millième de mètre carré, couramment utilisée dans les rapports médicaux, les mesures de laboratoire et les spécifications de petits produits. Les tailles de lésions cutanées, les échantillons de tissu et les composants de circuits imprimés sont souvent mesurés en centimètres carrés. Un centimètre carré équivaut exactement à 0,155 pouce carré.",
    "sqm": "Le mètre carré (m²) est l'unité de base du système international (SI) de surface, équivalente à un carré mesurant un mètre de chaque côté, utilisé dans le monde entier pour l'immobilier, la construction et l'arpentage. Les tailles d'appartements, les plans d'étage de bureaux et les coûts de construction sont presque universellement exprimés en mètres carrés en dehors des États-Unis. Un mètre carré équivaut à environ 10,764 pieds carrés.",
    "sqkm": "Le kilomètre carré (km²) équivaut à un million de mètres carrés et est utilisé pour mesurer de grandes superficies terrestres telles que les villes, les parcs nationaux et les pays. Les données géographiques, les rapports d'urbanisme et les études écologiques s'appuient sur les kilomètres carrés comme unité de surface standard. Un kilomètre carré équivaut à environ 0,3861 mile carré ou environ 247,1 acres.",
    "ha": "L'hectare (ha) est une unité de surface métrique équivalente à 10 000 mètres carrés ou 100 ares, largement utilisée en agriculture, en sylviculture et en gestion des terres à travers le monde. Les fermes, les vignobles et les réserves naturelles sont généralement décrits en hectares en Europe, en Asie et en Océanie. Un hectare équivaut à environ 2,471 acres, offrant un lien pratique entre les mesures foncières métriques et impériales.",
    "acre": "L'acre est une unité impériale de surface équivalente à 43 560 pieds carrés ou environ 4 047 mètres carrés, principalement utilisée aux États-Unis, au Royaume-Uni et dans les anciennes colonies britanniques pour la mesure des terres. Les annonces immobilières, les limites des terres agricoles et la taille des terrains suburbains dans ces régions sont traditionnellement exprimées en acres. Un acre équivaut à peu près à 90 % d'un terrain de football standard.",
    "sqft": "Le pied carré (ft²) est une unité de surface impériale équivalente à un carré mesurant un pied de chaque côté, la mesure standard pour la taille des maisons, les bureaux et les biens locatifs aux États-Unis. Les annonces immobilières en Amérique indiquent presque toujours la surface habitable en pieds carrés, ce qui en fait l'une des unités de surface les plus pratiquement pertinentes. Un pied carré équivaut exactement à 0,0929 mètre carré.",
    "sqin": "Le pouce carré (in²) est une petite unité impériale de surface égale à un carré mesurant un pouce de chaque côté, couramment utilisée dans les spécifications d'ingénierie, les descriptions de taille d'écran et les mesures de pression. Les surfaces de piston, les calculs de contraintes des matériaux et les tailles des composants électroniques sont fréquemment exprimés en pouces carrés. Un pouce carré équivaut exactement à 6,4516 centimètres carrés.",
    "sqmi": "Le mille carré (mi²) est une grande unité de superficie impériale égale à 640 acres ou environ 2,59 kilomètres carrés, utilisée pour mesurer des territoires étendus comme les villes, les comtés et les parcs nationaux. Les données géographiques aux États-Unis et au Royaume-Uni font fréquemment référence aux milles carrés lorsqu'elles décrivent des régions, en particulier dans les calculs de densité de population. Un mille carré équivaut exactement à 2,58999 kilomètres carrés.",
    "mu": "Le mu (亩) est une unité traditionnelle chinoise de superficie équivalente à environ 666,67 mètres carrés, largement utilisée dans l'agriculture chinoise, les contrats de terres rurales et les registres fonciers. Les terres agricoles en Chine sont presque toujours mesurées en mu, et les politiques gouvernementales concernant les quotas de production de céréales font référence à cette unité. Un mu équivaut à environ 0,1647 acre ou à environ 7 176 pieds carrés."
  },
  "volume": {
    "ml": "Le millilitre (mL) est une unité métrique de volume équivalente à un millième de litre, largement utilisée en médecine, en cuisine et en chimie pour mesurer de petites quantités de liquide. Les doses de sirop contre la toux, les flacons de parfum et les réactifs de laboratoire sont tous couramment étiquetés en millilitres. Un millilitre équivaut exactement à un centimètre cube, ce qui le rend interchangeable avec cm³ dans les contextes scientifiques.",
    "cl": "Le centilitre (cL) est une unité métrique de volume égale à un centième de litre, couramment utilisée dans les pays européens pour les tailles de bouteilles de boissons et de spiritueux. Les étiquettes de vin et de spiritueux dans l'UE affichent fréquemment le volume en centilitres en plus des millilitres. Un centilitre équivaut exactement à 10 millilitres ou environ 0,338 onces liquides.",
    "dl": "Le décilitre (dL) est une unité métrique de volume égale à un dixième de litre, utilisée dans les rapports de laboratoire médicaux et certaines recettes européennes. Les résultats des analyses de sang dans de nombreux pays expriment les niveaux de cholestérol et de glucose en milligrammes par décilitre, ce qui rend cette unité familière à toute personne consultant des données sur la santé. Un décilitre équivaut exactement à 100 millilitres ou environ 3,381 onces liquides.",
    "l": "Le litre (L) est l'unité de volume métrique la plus utilisée, équivalente à 1 000 centimètres cubes ou à un décimètre cube, servant de référence pour les boissons, le carburant et les liquides domestiques dans le monde entier. Les prix de l'essence, les bouteilles d'eau et les cartons de lait font tous référence aux litres dans la plupart des pays. Un litre équivaut à environ 1,0567 quarts américains ou 0,2642 gallons américains.",
    "m3": "Le mètre cube (m³) est l'unité de base du SI pour le volume, représentant l'espace occupé par un cube d'un mètre de côté, utilisé dans la construction, l'expédition et les processus industriels. Les factures d'approvisionnement en eau, les commandes de béton et les calculs de fret reposent tous sur le mètre cube comme mesure standard. Un mètre cube équivaut exactement à 1 000 litres ou environ 264,2 gallons américains.",
    "gal": "Le gallon américain (gal) est une unité de volume impériale équivalente exactement à 3,7854 litres, la mesure standard pour le carburant, le lait et la peinture aux États-Unis. Les prix de l'essence aux pompes américaines sont toujours indiqués par gallon, et l'efficacité énergétique des véhicules américains est mesurée en miles par gallon. Un gallon américain équivaut à 4 quarts américains ou 8 pintes américaines.",
    "gal_uk": "Le gallon britannique (gallon impérial) équivaut exactement à 4,54609 litres, soit environ 20 % de plus que le gallon américain, et reste la mesure standard de carburant au Royaume-Uni et dans certains pays du Commonwealth. L'efficacité énergétique britannique est exprimée en miles par gallon impérial, ce qui donne des chiffres plus élevés que l'équivalent américain. Un gallon britannique équivaut à environ 1,201 gallons américains.",
    "qt": "Le quart américain (qt) est une unité de volume impériale égale à un quart de gallon américain ou exactement 0,9464 litre, communément utilisée dans la cuisine américaine et les emballages alimentaires. Les conteneurs d'huile moteur et les bacs de crème glacée aux États-Unis utilisent fréquemment des mesures en quarts. Un quart américain équivaut exactement à 2 pintes américaines ou environ 32 onces liquides américaines.",
    "pt": "La pinte américaine (pt) est une unité de volume impériale équivalente à un huitième de gallon américain ou à environ 0,4732 litre, principalement connue pour la taille des verres à bière et des contenants de glace en Amérique. L'expression « a pint is a pound the world around » reflète son importance dans le langage courant, bien qu'une pinte d'eau pèse en réalité environ 1,043 livre. Une pinte américaine équivaut exactement à 16 onces liquides américaines.",
    "cup": "La tasse américaine est une unité de volume équivalente à 8 onces liquides américaines ou environ 0,2366 litre, la mesure standard dans les recettes et livres de cuisine américains. Lorsqu'une recette demande « une tasse de farine » ou « une demi-tasse de sucre », elle fait référence à ce volume spécifique, et non à un récipient à boire de taille arbitraire. Une tasse américaine équivaut exactement à 236,588 millilitres.",
    "floz": "L'once liquide américaine (fl oz) est une unité de volume équivalente à environ 29,574 millilitres, utilisée pour étiqueter les boissons, les cosmétiques et les produits de soins personnels aux États-Unis. Les canettes de boissons, les bouteilles de shampooing et les sérums pour la peau indiquent tous leur contenu en onces liquides pour les consommateurs américains. Une once liquide équivaut exactement à 1/128 d'un gallon américain ou à environ 2 cuillères à soupe.",
    "tbsp": "La cuillère à soupe (c. à s.) est une unité de volume équivalente à 3 cuillères à café ou environ 14,787 millilitres, principalement utilisée dans les recettes de cuisine et les étiquettes nutritionnelles. En cuisine, une cuillère à soupe de beurre, d'huile ou de sucre fournit une mesure constante indépendamment de la taille physique de la cuillère. Une cuillère à soupe américaine équivaut exactement à 0,5 once liquide américaine.",
    "tsp": "La cuillère à café (c. à c.) est la plus petite unité de volume standard en cuisine, équivalente à environ 4,929 millilitres, que l'on retrouve dans les recettes du monde entier pour mesurer de petites quantités d'épices, d'extraits et de médicaments. Elle sert de base pour des mesures plus grandes, trois cuillères à café équivalant à une cuillère à soupe. Une cuillère à café américaine équivaut exactement à 1/6 d'une once liquide américaine."
  },
  "speed": {
    "ms": "Mètres par seconde (m/s) est l'unité de base SI pour la vitesse et la vélocité, représentant la distance en mètres parcourue pendant une seconde. C'est l'unité standard en physique, en ingénierie et en recherche scientifique, utilisée pour décrire tout, des objets en chute libre aux débits de fluides. Un mètre par seconde équivaut exactement à 3,6 kilomètres par heure ou à environ 2,237 miles par heure.",
    "kmh": "Kilomètres par heure (km/h) est l'unité de vitesse la plus courante en dehors des États-Unis, affichée sur les compteurs de vitesse et les panneaux routiers à travers l'Europe, l'Asie et la majorité du monde. Les limites de vitesse sur les autoroutes, les bulletins météorologiques concernant la vitesse du vent et les performances des véhicules dans ces régions utilisent tous le km/h. Un kilomètre par heure équivaut approximativement à 0,2778 mètre par seconde ou environ 0,6214 miles par heure.",
    "mph": "Miles par heure (mph) est l'unité de vitesse standard aux États-Unis, au Royaume-Uni et dans quelques autres pays, utilisée pour les limites de vitesse, les compteurs de vitesse des véhicules et les prévisions météorologiques. Les panneaux routiers américains affichent exclusivement les limites de vitesse en mph, et les amateurs de voitures se réfèrent couramment aux temps de 0 à 60 mph comme indicateur de performance. Une mile par heure équivaut exactement à 1,60934 kilomètres par heure.",
    "kn": "Le nœud (kn) équivaut à un mille marin par heure ou environ 1,852 kilomètres par heure, l'unité de vitesse universelle pour la navigation maritime et aérienne. Les vitesses des navires, les vitesses des aéronefs et les vitesses du vent dans les rapports météorologiques utilisent toutes le nœud comme mesure standard. Un nœud équivaut exactement à 1,15078 miles par heure, ce qui reflète le mille marin plus long comparé au mille terrestre.",
    "fts": "Pieds par seconde (ft/s) est une unité de vitesse impériale couramment utilisée en balistique, en dynamique des fluides et dans les calculs d'ingénierie aux États-Unis. Les vitesses des projectiles, les débits dans les tuyaux et les vitesses des convoyeurs sont souvent exprimés en ft/s dans la documentation technique américaine. Un pied par seconde équivaut exactement à 0,3048 mètres par seconde ou environ 0,6818 miles par heure.",
    "mach": "Le Mach (Ma) est une unité de vitesse sans dimension représentant le rapport entre la vitesse d'un objet et la vitesse du son dans le milieu environnant. Au niveau de la mer dans des conditions standard, le Mach 1 est égal à environ 343 mètres par seconde ou 1 235 kilomètres par heure, bien que cela varie avec l'altitude et la température. Les avions supersoniques volent au-dessus de Mach 1, tandis que les véhicules hypersoniques dépassent Mach 5."
  },
  "time": {
    "ms_time": "La milliseconde (ms) est une unité de temps équivalente à un millième de seconde, cruciale en informatique, en télécommunications et dans les expériences scientifiques où le chronométrage précis est important. La latence réseau, la vitesse d'obturation des appareils photo et les mesures du temps de réaction fonctionnent toutes à l'échelle de la milliseconde. Une milliseconde équivaut exactement à 0,001 seconde, et l'œil humain peut à peine percevoir des changements plus rapides qu'environ 10 millisecondes.",
    "s": "La seconde (s) est l'unité de base du temps dans le Système international d'unités, définie par la fréquence de vibration des atomes de césium-133. Elle sert de fondement à toutes les mesures de temps, des horloges et montres aux satellites GPS et à la physique atomique. Une seconde équivaut exactement à 1 000 millisecondes et est divisée en 60 secondes par minute.",
    "min": "La minute (min) est une unité de temps équivalente à 60 secondes, utilisée universellement pour la planification, les minuteries de cuisine et la mesure du temps quotidienne. La durée des réunions, les intervalles d'exercice et les horaires de transport dépendent tous des minutes comme unité principale. Une minute équivaut exactement à 60 secondes, et 60 minutes constituent une heure.",
    "h": "L'heure (h) est une unité de temps égale à 60 minutes ou 3 600 secondes, la mesure standard pour les horaires de travail, les temps de trajet et les heures d'ouverture dans le monde entier. Les calculs de paie, les durées des vols et les horaires quotidiens sont tous structurés autour des heures. Une heure équivaut exactement à 3 600 secondes, et 24 heures constituent un jour.",
    "d": "Le jour (d) est une unité de temps équivalente à 24 heures ou 86 400 secondes, représentant une rotation complète de la Terre sur son axe. C'est le cycle fondamental pour l'activité humaine, organisant les horaires de travail, les cycles de sommeil et les systèmes calendaires à travers toutes les cultures. Un jour équivaut exactement à 86 400 secondes ou 1 440 minutes.",
    "wk": "La semaine (sem) est une unité de temps égale à 7 jours ou 168 heures, servant de période standard d'organisation pour les cycles commerciaux, les emplois du temps scolaires et les périodes de paie dans la plupart des cultures. Les calendriers de projet, les plans de remise en forme et les événements récurrents sont généralement planifiés sur une base hebdomadaire. Une semaine équivaut exactement à 7 jours ou 604 800 secondes.",
    "mo": "Le mois (mo) est une unité de temps représentant en moyenne environ 30,44 jours ou 2 629 746 secondes, utilisée pour les cycles de facturation, les contrats de location et la planification financière. Les mois du calendrier varient de 28 à 31 jours, mais le mois moyen fournit une référence cohérente pour les calculs à long terme. Un mois moyen équivaut à environ 4,345 semaines ou environ 730,5 heures.",
    "yr": "L'année (an) est une unité de temps équivalente à environ 365,25 jours ou 31 557 600 secondes, représentant une orbite complète de la Terre autour du Soleil. C'est l'unité principale pour l'âge, les rapports financiers, les taux d'intérêt et les contrats à long terme, le surplus d'un quart de jour étant géré par les années bissextiles. Une année équivaut à environ 52,18 semaines ou environ 8 766 heures."
  },
  "pressure": {
    "pa": "Le pascal (Pa) est l'unité de base de pression du SI, définie comme un newton par mètre carré, utilisée en physique, en ingénierie et en science des matériaux. Bien qu'il soit la norme scientifique, les pressions quotidiennes sont plus communément exprimées en kilopascals ou en mégapascals car un pascal représente une pression extrêmement faible. Un pascal équivaut à 0,00001 bar ou environ 0,000145 psi.",
    "kpa": "Le kilopascal (kPa) équivaut à 1 000 pascals et est l'unité la plus pratique pour les mesures de pression quotidiennes dans les pays utilisant le système métrique. La pression des pneus, les spécifications des bâtiments et les bulletins météorologiques au Canada, en Australie et en Europe utilisent couramment les kilopascals. Un kilopascal équivaut à 0,01 bar ou environ 0,145 psi, ce qui en fait un compromis pratique entre les échelles scientifiques et industrielles.",
    "mpa": "Le mégapascal (MPa) équivaut à un million de pascals et est l'unité standard pour les applications à haute pression en ingénierie structurelle, en essais de matériaux et en systèmes hydrauliques. La résistance du béton est évaluée en mégapascals, et les spécifications de résistance à la traction de l'acier font régulièrement référence à cette unité. Un mégapascal équivaut à 10 bars ou approximativement 145 psi, assurant la liaison entre les échelles de pression métrique et impériale.",
    "bar": "Le bar est une unité de pression métrique égale à 100 000 pascals, largement utilisée en météorologie, océanographie et applications industrielles car elle approche de près la pression atmosphérique au niveau de la mer. Les manomètres de pneus en Europe, les profondeurs de plongée sous-marine et les cartes météorologiques font tous fréquemment référence aux bars ou millibars. Un bar équivaut à environ 0,9869 atmosphères ou 14,504 psi.",
    "atm": "L'atmosphère standard (atm) est une unité de pression définie exactement comme 101 325 pascals, représentant la pression atmosphérique moyenne au niveau de la mer sur Terre. Elle sert de point de référence en chimie pour les calculs des lois des gaz et en ingénierie pour évaluer la capacité des récipients sous pression. Une atmosphère équivaut approximativement à 1,01325 bar, 14,696 psi ou 760 mmHg.",
    "psi": "PSI (livres par pouce carré) est une unité de pression impériale équivalente à environ 6 894,76 pascals, la mesure standard pour la pression des pneus, les systèmes à air comprimé et les équipements hydrauliques aux États-Unis. Presque toutes les pompes à air et nettoyeurs haute pression des stations-service américaines affichent les valeurs en PSI, ce qui en fait l'une des unités de pression les plus reconnues dans le monde. Un PSI équivaut à environ 0,06895 bar ou 6,895 kPa.",
    "mmhg": "Le millimètre de mercure (mmHg) est une unité de pression équivalente à environ 133,322 pascals, traditionnellement utilisée en médecine pour mesurer la pression artérielle et en météorologie pour les relevés barométriques. Une pression artérielle normale chez l'adulte de 120/80 mmHg est universellement comprise par les professionnels de santé, ce qui fait de cette unité un élément incontournable dans les milieux cliniques. Un mmHg équivaut à environ 0,01934 psi ou 0,1333 kPa.",
    "torr": "Le torr est une unité de pression nommée d'après Evangelista Torricelli, équivalente à environ 133,322 pascals, utilisée principalement en physique des vides et dans la recherche en haute altitude. Il est presque identique au millimètre de mercure, un torr étant défini exactement comme 1/760 d'une atmosphère standard. Les pompes à vide, les microscopes électroniques et les équipements de fabrication de semi-conducteurs spécifient couramment les pressions de fonctionnement en torr."
  },
  "energy": {
    "j": "Le joule (J) est l'unité de base de l'énergie du SI, définie comme le travail effectué lorsqu'une force d'un newton déplace un objet d'un mètre. C'est l'unité universelle en physique pour mesurer l'énergie cinétique, la chaleur et l'énergie électrique, apparaissant dans tout, des problèmes de manuels scolaires à la science de la nutrition. Un joule équivaut à l'énergie libérée en laissant tomber une petite pomme d'un mètre, ce qui le rend tangible malgré sa faible magnitude.",
    "kj": "Le kilojoule (kJ) équivaut à 1 000 joules et est l'unité standard pour exprimer la teneur en énergie des aliments et les énergies des réactions chimiques dans les pays utilisant le système métrique. Les étiquettes alimentaires en Australie, en Europe et dans de nombreuses autres régions affichent les valeurs énergétiques en kilojoules, soit en parallèle des calories, soit à la place de celles-ci. Un kilojoule équivaut approximativement à 238,8 calories ou à environ 0,239 kilocalorie.",
    "cal": "La calorie (cal) est une petite unité d'énergie définie comme la quantité de chaleur nécessaire pour élever d'un degré Celsius un gramme d'eau, principalement utilisée en physique et en chimie. Dans le langage courant, « calorie » fait généralement référence à la kilocalorie (kcal), mais la véritable calorie représente 1/1 000 de cette quantité. Une calorie équivaut exactement à 4,184 joules, fournissant un lien direct entre l'énergie thermique et mécanique.",
    "kcal": "La kilocalorie (kcal), couramment appelée « Calorie » sur les étiquettes alimentaires, équivaut à 1 000 calories ou 4 184 joules, l'unité standard pour mesurer l'énergie alimentaire dans le monde. Lorsque les informations nutritionnelles indiquent « 200 Calories », cela signifie 200 kilocalories, représentant l'énergie que votre corps peut extraire de cet aliment. Une kilocalorie équivaut exactement à 4,184 kilojoules, la valeur utilisée sur les emballages alimentaires dans de nombreux pays.",
    "kwh": "Le kilowattheure (kWh) équivaut à 3 600 000 joules et est l'unité de facturation standard pour la consommation d'électricité résidentielle et commerciale dans le monde entier. Les compagnies d'électricité facturent au kilowattheure, et comprendre cette unité aide les consommateurs à évaluer les coûts de fonctionnement des appareils et la production des panneaux solaires. Un kilowattheure représente l'énergie utilisée par un appareil de 1 000 watts fonctionnant pendant une heure.",
    "btu": "Le BTU (British Thermal Unit) équivaut à environ 1 055,06 joules, défini comme la chaleur nécessaire pour élever d’un degré Fahrenheit la température d’une livre d’eau. C'est l'unité principale pour évaluer les équipements de chauffage et de climatisation aux États-Unis, apparaissant sur les spécifications des climatiseurs, les indices des chaudières et les étiquettes d'efficacité énergétique. Un BTU équivaut à environ 0,2931 watt-heure ou à peu près 0,252 kilocalories.",
    "wh": "Le watt-heure (Wh) équivaut à 3 600 joules, représentant l'énergie consommée par un appareil d'un watt fonctionnant pendant une heure. Il est couramment utilisé pour les petites capacités de batterie, les puissances de sortie des panneaux solaires et les métriques de recharge des véhicules électriques lorsque le kilowatt-heure serait une unité trop grande. Un watt-heure équivaut exactement à 0,001 kilowatt-heure ou à environ 3,412 BTU."
  },
  "power": {
    "w": "Le watt (W) est l'unité de base du SI pour la puissance, défini comme un joule par seconde, mesurant le taux de transfert d'énergie. Des évaluations de luminosité des ampoules aux sorties des chargeurs de téléphone, le watt apparaît dans les spécifications des produits du quotidien dans le monde entier. Un watt équivaut exactement à 1 joule par seconde, soit environ 0,001341 cheval-vapeur.",
    "kw": "Le kilowatt (kW) équivaut à 1 000 watts et est l'unité standard pour mesurer la puissance des moteurs, des chauffages électriques et des machines industrielles. Les factures d'électricité utilisent le kilowatt-heure (kW × heures), ce qui fait du kilowatt l'unité de puissance la plus familière pour les consommateurs. Un kilowatt équivaut à environ 1,341 cheval-vapeur.",
    "mw": "Le mégawatt (MW) équivaut à un million de watts, utilisé pour exprimer la production des centrales électriques, des grandes installations industrielles et des centres de données. Une éolienne typique génère 2 à 3 MW, tandis qu'une grande centrale à charbon peut produire 500 à 1 000 MW. Un mégawatt peut alimenter environ 800 à 1 000 maisons simultanément.",
    "hp": "La puissance en chevaux (ch) est une unité impériale de puissance équivalente à environ 745,7 watts, définie à l'origine par James Watt pour comparer la production des moteurs à vapeur à celle des chevaux de trait. Elle reste l'unité standard pour évaluer les moteurs de voitures, de tondeuses à gazon et de moteurs de bateaux, en particulier aux États-Unis. Un cheval-vapeur équivaut à environ 0,7457 kilowatts ou 1,0139 cheval-vapeur métrique.",
    "ps": "Le cheval-vapeur métrique (PS, Pferdestärke) équivaut à environ 735,5 watts, légèrement moins que le cheval-vapeur impérial, et est l'unité de puissance standard pour les classements de véhicules dans toute l'Europe et l'Asie. Les spécifications des voitures en Allemagne, au Japon et en Chine indiquent généralement la puissance du moteur en PS. Un PS équivaut à environ 0,9863 cheval-vapeur impérial ou 0,7355 kilowatts.",
    "btuh": "BTU par heure (BTU/h) équivaut à environ 0,293 watts, l'unité de mesure standard pour les climatiseurs, les chauffages et les chaudières en Amérique du Nord. Un climatiseur de fenêtre typique évalué à 10 000 BTU/h peut refroidir une pièce de 400 à 500 pieds carrés, ce qui rend cette unité essentielle pour le dimensionnement des systèmes CVC. Un BTU/h équivaut à environ 0,2931 watts.",
    "ftlbs": "Les pieds-livres par seconde (ft·lbf/s) équivalent à environ 1,356 watts, une unité de puissance impériale parfois utilisée dans des contextes de génie mécanique. Bien que moins courante que le cheval-vapeur pour les puissances moteur, elle fournit un lien direct entre le couple et la vitesse de rotation. Un pied-livre par seconde équivaut à environ 1,356 watts ou 0,00182 cheval-vapeur.",
    "calps": "Calories par seconde (cal/s) équivalent exactement à 4,184 watts, utilisées principalement en thermodynamique et en physique pour exprimer les taux de transfert de chaleur. Bien qu'il ne s'agisse pas d'une unité courante au quotidien, elle fait le lien entre les calculs de puissance thermique et mécanique dans la recherche scientifique. Une calorie par seconde équivaut exactement à 4,184 watts ou environ 0,00561 cheval-vapeur."
  },
  "fuel": {
    "kml": "Kilomètres par litre (km/L) est la mesure standard de l'efficacité énergétique utilisée dans la plupart des pays en dehors des États-Unis et du Royaume-Uni, mesurant la distance parcourue par un véhicule avec un litre de carburant. Une voiture compacte typique atteint 12 à 18 km/L, tandis que les hybrides peuvent dépasser 25 km/L. Un km/L équivaut à environ 2,352 miles par gallon américain.",
    "l100": "Les litres par 100 km (L/100 km) sont la mesure inverse de l'efficacité énergétique utilisée en Europe et en Australie, mesurant combien de litres de carburant un véhicule consomme sur 100 kilomètres. Des chiffres plus bas signifient une meilleure efficacité — une voiture évaluée à 5 L/100 km consomme moins de carburant qu'une voiture évaluée à 8 L/100 km. Il s'agit de l'inverse de km/L : L/100 km = 100 / km/L.",
    "mpg_us": "Les miles par gallon US (mpg) mesurent combien de miles un véhicule peut parcourir avec un gallon US (3,785 litres) de carburant, la référence standard d'efficacité aux États-Unis. Les évaluations de consommation de carburant de l'EPA américaine affichent les chiffres de mpg en ville et sur autoroute pour chaque véhicule neuf. Un mpg US équivaut à environ 0,425 km/L ou environ 23,52 L/100 km.",
    "mpg_uk": "Les miles par gallon au Royaume-Uni (mpg impérial) mesurent la distance parcourue par gallon impérial (4,546 litres), utilisés au Royaume-Uni pour les évaluations de consommation de carburant. Comme le gallon impérial est plus grand que le gallon américain, la même voiture affiche un chiffre de mpg plus élevé dans le système britannique. Un mpg britannique équivaut à environ 0,354 km/L ou environ 28,25 L/100 km."
  },
  "frequency": {
    "hz": "Le hertz (Hz) est l'unité de base SI de la fréquence, définie comme un cycle par seconde, mesurant la fréquence à laquelle un événement répétitif se produit. De la fréquence du réseau électrique en courant alternatif (50 ou 60 Hz) aux tonalités audio et aux vitesses d'horloge des processeurs, le hertz est le langage universel de la fréquence. Un hertz équivaut exactement à un cycle par seconde.",
    "khz": "Le kilohertz (kHz) équivaut à 1 000 hertz, couramment utilisé pour décrire les fréquences audio, les bandes de radiodiffusion et les vitesses des premiers processeurs informatiques. L'audition humaine varie d'environ 20 Hz à 20 kHz, ce qui rend cette unité essentielle en ingénierie audio et en production musicale. Un kilohertz équivaut à 1 000 cycles par seconde.",
    "mhz": "Le mégahertz (MHz) équivaut à un million de hertz, largement utilisé pour les bandes de fréquences radio, les premières vitesses d'horloge des CPU et les standards de communication sans fil. La radio FM diffuse dans la plage de 88 à 108 MHz, tandis que les premiers ordinateurs personnels fonctionnaient à seulement quelques MHz. Un mégahertz équivaut à 1 000 000 de cycles par seconde.",
    "ghz": "Le gigahertz (GHz) équivaut à un milliard de hertz, l'unité standard pour les vitesses d'horloge des processeurs modernes, les fréquences Wi-Fi et les bandes cellulaires 5G. Un processeur d'ordinateur portable typique fonctionne à 2–5 GHz, tandis que le Wi-Fi fonctionne à 2,4 GHz ou 5 GHz. Un gigahertz équivaut à 1 000 mégahertz ou un milliard de cycles par seconde.",
    "rpm": "Les révolutions par minute (rpm) mesurent la vitesse de rotation, en indiquant combien de tours complets un objet effectue en une minute. C'est l'unité la plus courante pour la vitesse des moteurs, la vitesse de rotation des disques durs et les caractéristiques des outils électriques dans le monde entier. Une rpm équivaut exactement à 1/60 hertz ou environ 0,01667 Hz.",
    "rps": "Les révolutions par seconde (rps) mesurent la vitesse de rotation en tours complets par seconde, équivalant exactement à un hertz. Bien que moins courant que le rpm dans les spécifications quotidiennes, le rps est utilisé en physique, en analyse d'ingénierie et dans certaines classifications d'équipements industriels. Un rps équivaut exactement à 60 rpm."
  },
  "angle": {
    "deg": "Le degré (°) est l'unité la plus courante pour mesurer les angles, divisant un cercle complet en 360 parties égales. De la navigation et de la construction à la géométrie quotidienne, les degrés sont l'unité angulaire par défaut dans le monde entier. Un degré équivaut à π/180 radians ou environ 0,01745 radians.",
    "rad": "Le radian (rad) est l'unité SI de mesure des angles, définie comme l'angle sous-tendu par un arc de longueur égale au rayon du cercle. C'est l'unité naturelle pour les fonctions trigonométriques en mathématiques et en physique — sin, cos et tan supposent toutes une entrée en radians. Un radian équivaut à environ 57,296 degrés.",
    "grad": "Le gradian (gon), également appelé grad, divise un angle droit en 100 parties égales, ce qui fait qu'un cercle complet compte 400 gradians. Il est utilisé principalement en arpentage et dans certains systèmes cartographiques militaires européens, où le système décimal base 100 simplifie les calculs décimaux. Un gradian équivaut exactement à 0,9 degré.",
    "arcmin": "L'arcminute (′) équivaut à 1/60 de degré, utilisé en astronomie, en cartographie et en navigation de précision là où une résolution angulaire fine est nécessaire. Les étoiles sont cataloguées par leurs coordonnées en degrés et en arcminutes, et la précision de pointage des télescopes est souvent spécifiée en arcminutes. Un arcminute équivaut à 1/60 de degré ou environ 0,000291 radians.",
    "arcsec": "La seconde d'arc (″) équivaut à 1/3 600 d'un degré, offrant une résolution angulaire extrêmement fine pour l'astronomie, l'optique et l'imagerie par satellite. Le télescope spatial Hubble a une résolution d'environ 0,05 seconde d'arc, et les mesures de parallaxe stellaire utilisent une précision de millisecondes d'arc. Une seconde d'arc équivaut à 1/3600 de degré ou environ 0,00000485 radian.",
    "turn": "Un tour (tr), également appelé révolution, représente une rotation complète de 360 degrés ou 2π radians. Il est utilisé dans des contextes d'ingénierie impliquant la mécanique de rotation, les spécifications des moteurs électriques et les calculs de vitesse angulaire où les rotations complètes sont plus intuitives que les degrés ou les radians. Un tour équivaut exactement à 360 degrés."
  },
  "force": {
    "n": "Le newton (N) est l'unité de base SI de la force, définie comme la force nécessaire pour accélérer un kilogramme de masse à un mètre par seconde au carré. Nommé d'après Isaac Newton, c'est l'unité fondamentale en mécanique, en ingénierie structurelle et en physique dans le monde entier. Un newton équivaut à environ 0,2248 livre-force.",
    "kn": "Le kilonewton (kN) équivaut à 1 000 newtons, utilisé en génie civil pour exprimer les charges des bâtiments, les capacités des ponts et les indices de résistance des matériaux. Une voiture de tourisme typique pèse environ 10 à 15 kN, et les codes du bâtiment spécifient les charges de conception en kN par mètre carré. Un kilonewton équivaut à environ 224,8 livres-force.",
    "lbf": "La livre-force (lbf) est l'unité impériale standard de force aux États-Unis, définie comme la force gravitationnelle exercée sur une livre de masse au niveau de la mer. Elle apparaît dans les spécifications de tension des boulons, les tests de matériaux et les spécifications d'ingénierie mécanique en Amérique du Nord. Une livre-force équivaut à environ 4,448 newtons.",
    "kgf": "Le kilogramme-force (kgf) est une unité non SI définie comme la force gravitationnelle exercée sur un kilogramme de masse à la gravité standard, égale exactement à 9,80665 newtons. Elle est couramment utilisée dans certains domaines de l'ingénierie et dans les pays en transition des unités techniques métriques vers le SI. Un kilogramme-force équivaut à environ 2,205 livres-force.",
    "dyn": "Le dyne (dyn) est une unité de force du système centimètre-gramme-seconde (CGS) égale exactement à 0,00001 newton, utilisée principalement en physique pour les calculs de forces à petite échelle. Il représente la force nécessaire pour accélérer un gramme de masse à un centimètre par seconde au carré, et apparaît dans les mesures de tension superficielle et de force électromagnétique. Un dyne équivaut exactement à 10 micronewtons.",
    "ozf": "L'once-force (ozf) équivaut à environ 0,278 newtons, l'unité impériale pour les petites mesures de force en ingénierie de précision, le calibrage des ressorts et les tests micromécaniques. Elle est particulièrement utile pour mesurer le poids de la traction des gâchettes, les petites tensions de ressorts et les calibrages délicats d'instruments. Une once-force équivaut à environ 1/16 de livre-force."
  },
  "torque": {
    "nm": "Le newton-mètre (N·m) est l'unité SI du couple, mesurant la force de rotation produite lorsqu'une force d'un newton est appliquée à un mètre de distance du point de pivot. C'est l'unité standard pour les spécifications de couple des moteurs, les exigences de serrage des boulons et la conception mécanique dans le monde entier. Un newton-mètre équivaut approximativement à 0,7376 livre-pieds.",
    "kNm": "Le kilonewton-mètre (kN·m) équivaut à 1 000 newton-mètres, utilisé en génie civil et en génie structurel pour les spécifications de couple à grande échelle sur les ponts, les grues et les équipements industriels lourds. Les spécifications des boulons de fondation et les cotes de couple des éoliennes sont couramment exprimées en kN·m. Un kN·m équivaut à environ 737,6 livres-pieds.",
    "lbft": "Livre-pied (lb·ft) est l'unité impériale de couple principalement utilisée aux États-Unis et au Royaume-Uni pour les spécifications des moteurs automobiles et le serrage des fixations mécaniques. Les passionnés de voitures discutent de la puissance du moteur en lb·ft, et les clés dynamométriques aux États-Unis sont étalonnées dans cette unité. Un livre-pied équivaut à environ 1,356 newton-mètre.",
    "lbin": "Le pound-inch (lb·in) est une unité de couple impériale utilisée pour des applications de précision plus petites, couramment employée pour l'assemblage électronique, les spécifications de petits moteurs et l'étalonnage des instruments. Les tournevis à couple et les spécifications de fixations de précision aux États-Unis utilisent généralement le lb·in. Un pound-inch équivaut à environ 0,113 newton-mètre ou 1/12 de pound-foot.",
    "kgfm": "Le kilogramme-force mètre (kgf·m) est une unité technique métrique de couple couramment utilisée au Japon, en Chine et dans d'autres pays asiatiques pour les spécifications des moteurs et des moteurs électriques. Bien qu'elle ne fasse pas partie du système SI, elle reste une norme dans les spécifications automobiles à travers l'Asie de l'Est. Un kgf·m équivaut approximativement à 9,807 newton-mètres ou à environ 7,233 pieds-livres.",
    "ozin": "L'once-pouce (oz·in) est une petite unité de couple impériale utilisée pour les instruments de précision, l'horlogerie et l'assemblage micro-mécanique où même les livres-pouces seraient trop grands. Les petits servomoteurs, les mécanismes d'objectifs d'appareils photo et les fixations électroniques délicates sont évalués en oz·in. Une once-pouce équivaut à environ 0,00706 newton-mètres."
  },
  "shoe": {
    "cm": "Les centimètres (cm) représentent la mesure réelle de la longueur du pied, le point de référence universel pour tous les systèmes de conversion de pointure. Mesurer d'abord votre pied en centimètres est la manière la plus fiable de trouver votre taille correcte dans les systèmes américain, britannique, européen et japonais, car chaque région utilise des échelles de numérotation différentes. Un pied masculin adulte typique mesure 26 à 28 cm.",
    "us_m": "Les tailles de chaussures pour hommes aux États-Unis suivent une échelle où la taille 9 correspond à une longueur de pied d'environ 27 cm, chaque demi-taille ajoutant environ 0,42 cm. Le système américain est utilisé dans toute l'Amérique du Nord et diffère des tailles britanniques d'environ une taille complète (US 9 ≈ UK 8). Les tailles de chaussures de sport peuvent légèrement varier selon les marques.",
    "us_w": "Les tailles de chaussures pour femmes aux États-Unis sont approximativement de 1,5 point plus grandes en nombre que celles des hommes pour la même longueur de pied, la taille 9 pour femmes aux États-Unis correspondant à environ 25,4 cm de longueur de pied. Ce décalage cause souvent de la confusion lors de l'achat de chaussures unisexes ou de sport. US Women's 9 ≈ US Men's 7,5 ≈ EU 40 ≈ UK 6,5.",
    "uk": "Les tailles de chaussures britanniques sont la base du système américain mais décalées d'environ une taille — le 8 UK correspond à un 9 US pour hommes et à une longueur de pied d'environ 27 cm. Le système britannique est utilisé dans toute la Grande-Bretagne, l'Irlande et de nombreux pays du Commonwealth, et il correspond étroitement au système de taille de chaussures indien.",
    "eu": "Les tailles de chaussures EU (également appelées tailles continentales ou Paris Point) utilisent une échelle où chaque incrément de taille équivaut à 2/3 cm (6,67 mm) de longueur de pied, ce qui fait que la taille EU 42 correspond à environ 26,7 cm. Le système EU est utilisé dans toute l'Europe continentale et est la norme internationale la plus courante. Convertir entre les tailles EU et US/UK nécessite de connaître la longueur du pied.",
    "jp": "Les tailles de chaussures japonaises (également utilisées en Corée) représentent directement la longueur du pied en millimètres — JP 260 signifie un pied de 26 cm, JP 270 signifie 27 cm. Cela rend le système japonais le plus simple et le plus intuitif, car le numéro de taille correspond directement à la mesure du pied. Les tailles japonaises vont généralement de 230 (femmes) à 290 (grande taille hommes)."
  }
};
